// src/pages/ProfilePage.jsx
import React, { useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { toast } from "react-toastify";
import { motion } from "framer-motion";
import { User, Mail, Phone, MapPin, Save, ShieldCheck } from "lucide-react";
import userService from "../services/userService";
import { setCredentials } from "../context/authSlice";

export default function ProfilePage() {
  const { user } = useSelector((state) => state.auth);
  const dispatch = useDispatch();
  const [form, setForm] = useState({ ...user });
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await userService.update(user.id, form);
      dispatch(setCredentials({ user: form, token: localStorage.getItem("token") }));
      toast.success("Cập nhật thông tin thành công!");
    } catch (err) {
      toast.error("Không thể cập nhật hồ sơ");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto px-6 py-12">
      <div className="mb-8 border-b border-slate-200 pb-5">
        <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tight">Hồ sơ cá nhân</h1>
      </div>

      <motion.form 
        initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}
        onSubmit={handleSubmit} className="bg-white border border-slate-200 rounded-3xl p-8 shadow-3xs space-y-5"
      >
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="text-[11px] font-bold text-slate-400 uppercase">Họ tên</label>
            <input name="fullname" value={form.fullname} onChange={handleChange} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 mt-1 text-xs font-semibold focus:border-blue-600 outline-none" />
          </div>
          <div>
            <label className="text-[11px] font-bold text-slate-400 uppercase">Email</label>
            <input name="email" value={form.email} disabled className="w-full bg-slate-100 border border-slate-200 rounded-xl px-4 py-2.5 mt-1 text-xs font-semibold cursor-not-allowed" />
          </div>
          <div>
            <label className="text-[11px] font-bold text-slate-400 uppercase">Số điện thoại</label>
            <input name="phone" value={form.phone} onChange={handleChange} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 mt-1 text-xs font-semibold focus:border-blue-600 outline-none" />
          </div>
        </div>
        <div>
          <label className="text-[11px] font-bold text-slate-400 uppercase">Địa chỉ</label>
          <textarea name="address" value={form.address} onChange={handleChange} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 mt-1 text-xs font-semibold focus:border-blue-600 outline-none" />
        </div>
        <button type="submit" disabled={loading} className="bg-blue-600 text-white font-black text-xs uppercase px-6 py-3 rounded-xl hover:bg-blue-700 transition">
          {loading ? "Đang lưu..." : "Lưu thay đổi"}
        </button>
      </motion.form>
      
    </div>
  );
}
